import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/app.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.before_request
def check_api_key():
    # Internal health check bypass
    if request.path == '/health':
        return None
    key = request.headers.get('X-API-Key', '')
    if not key:
        return jsonify({'error': 'Missing API key'}), 401
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (key,)).fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403
    g.current_user = dict(user)

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/users/search')
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Whitelist allowed search fields
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query with validated field name but injectable value
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>')
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Username required'}), 400
    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, role, api_key) VALUES (?, ?, ?, ?)',
            (data['username'], data.get('email', ''), 'user', os.urandom(16).hex())
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/api/admin/export')
def export_data():
    if g.current_user.get('role') != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    db = get_db()
    users = db.execute('SELECT * FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]})

@app.route('/api/admin/run-report')
def run_report():
    """Generate report - admin only"""
    if g.current_user.get('role') != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    report_type = request.args.get('type', 'summary')
    # Potentially dangerous but admin-only
    result = os.popen(f'echo "Report: {report_type}" && date').read()
    return jsonify({'report': result})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
